def longest_subsequence_sum_length(nums,target):
    best=[-1]*(target+1);best[0]=0
    for value in nums:
        for total in range(target,value-1,-1):
            if best[total-value]>=0:best[total]=max(best[total],best[total-value]+1)
    return best[target]

